    fl_object_t* obj = malloc(sizeof(fl_object_t));
    obj->capacity = capacity > 0 ? capacity : 10;
    obj->size = 0;
    obj->keys = malloc(obj->capacity * sizeof(char*));
    obj->values = malloc(obj->capacity * sizeof(fl_value_t));
    return obj;
}

