#include "../include/runtime.h"

/* Helper functions */
static fl_value_t fl_new_null() {
    fl_value_t result;
    result.type = FL_TYPE_NULL;
    return result;
}

static fl_value_t fl_new_int(fl_int val) {
    fl_value_t result;
