    const char* str = args[0].data.string_val;
    fl_int idx = (args[1].type == FL_TYPE_INT) ? args[1].data.int_val : 0;

    if (idx < 0 || idx >= (fl_int)strlen(str)) {
        return fl_new_null();
    }

    char ch[2] = {str[idx], '\0'};
    return fl_new_string(ch);
