void fl_value_print(fl_value_t value) {
    switch (value.type) {
        case FL_TYPE_NULL:
            printf("null");
            break;
        case FL_TYPE_BOOL:
            printf("%s", value.data.bool_val ? "true" : "false");
            break;
        case FL_TYPE_INT:
            printf("%ld", value.data.int_val);
            break;
        case FL_TYPE_FLOAT:
            printf("%g", value.data.float_val);
            break;
        case FL_TYPE_STRING:
            printf("%s", value.data.string_val ? value.data.string_val : "");
            break;
        case FL_TYPE_ARRAY:
            printf("[array]");
            break;
        case FL_TYPE_OBJECT:
            printf("{...}");
            break;
        case FL_TYPE_FUNCTION:
            printf("[function]");
            break;
        case FL_TYPE_CLOSURE:
            printf("[closure]");
