     */
    if (argc < 2 || args[0].type != FL_TYPE_ARRAY) {
        return fl_new_null();
    }

    fl_array_t* src_arr = args[0].data.array_val;
    fl_array_t* result_arr = fl_array_create(src_arr->capacity);

    /* If a callback function is provided (future feature), apply it
