// ============================================================

class X86Encoder {
  constructor() {
    this.code = [];
  }

  // mov rdi, imm64
  mov_rdi_imm64(value) {
    this.code.push(0x48);
    this.code.push(0xbf);
    if (typeof value === 'bigint') value = Number(value);
    // Little-endian 64-bit
    for (let i = 0; i < 8; i++) {
      this.code.push((value >> (i * 8)) & 0xFF);
    }
  }

  // mov rsi, imm64
  mov_rsi_imm64(value) {
