    for (let i = 0; i < 8; i++) {
      this.code.push((value >> (i * 8)) & 0xFF);
    }
  }

  // mov rax, imm64
  mov_rax_imm64(value) {
    this.code.push(0x48);
    this.code.push(0xb8);
    if (typeof value === 'bigint') value = Number(value);
    for (let i = 0; i < 8; i++) {
      this.code.push((value >> (i * 8)) & 0xFF);
    }
  }

  // syscall
  syscall() {
    this.code.push(0x0f);
    this.code.push(0x05);
  }

  // ret
  ret() {
    this.code.push(0xc3);
  }

  // call rel32
  call_rel32(offset) {
    this.code.push(0xe8);
    // Offset relative to next instruction
    let rel = offset - (this.code.length + 4);
    for (let i = 0; i < 4; i++) {
      this.code.push((rel >> (i * 8)) & 0xFF);
    }
  }

  getBytes() {
    return Buffer.from(this.code);
